import Fastify from "fastify";

type Product = { id: string; name: string; price: number };
const products: Product[] = [{ id: "notebook", name: "Notebook", price: 4.5 }];

export const app = Fastify({ logger: false });

app.get<{ Params: { id: string }; Reply: Product | { error: string } }>(
    "/products/:id",
    {
        schema: {
            params: {
                type: "object",
                required: ["id"],
                properties: { id: { type: "string" } },
            },
            response: {
                200: {
                    type: "object",
                    required: ["id", "name", "price"],
                    properties: {
                        id: { type: "string" },
                        name: { type: "string" },
                        price: { type: "number" },
                    },
                },
                404: {
                    type: "object",
                    required: ["error"],
                    properties: { error: { type: "string" } },
                },
            },
        },
    },
    async function getProduct(request, reply) {
        const product = products.find(function match(item) {
            return item.id === request.params.id;
        });
        if (product === undefined) {
            return reply.status(404).send({ error: "not_found" });
        }
        return product;
    },
);
